internal class UPSBasePriceVersionCopy extends RunBase
{
    UPSBasePriceVersion     callerBasePriceVersion;

    UPSBasePriceVersionId   versionId;
    UPSBasePriceVersionName versionName;
    DialogField             versionIdDlgField;
    DialogField             versionNameDlgField;

    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
        callerBasePriceVersion,
        versionId,
        versionName
    #ENDMACRO

}

Method.Source:
public static UPSBasePriceVersionCopy construct()
{
    return new UPSBasePriceVersionCopy();
}

public boolean unpack(container packedClass)
{
    Integer     version         = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList] = packedClass;

            break;

        default :
            return false;
    }

    return true;
}

public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.addGroup("@UnifiedPricingService:UPSBasePriceVersionTable");
    versionIdDlgField   = dialog.addFieldValue(extendedTypeStr(UPSBasePriceVersionId), versionId);
    versionNameDlgField = dialog.addFieldValue(extendedTypeStr(UPSBasePriceVersionName), versionName);

    return dialog;
}

public boolean getFromDialog()
{
    boolean ret = super();

    versionId   = versionIdDlgField.value();
    versionName = versionNameDlgField.value();

    return ret;
}

public static void main(Args args)
{
    UPSBasePriceVersion             basePriceVersion;
    UPSBasePriceVersionCopy         basePriceVersionCopy;
    Common                          record;

    using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
    {
        basePriceVersionCopy = UPSBasePriceVersionCopy::construct();
        if (basePriceVersionCopy.prompt())
        {
            if (basePriceVersionCopy.initFromArgs(args))
            {
                basePriceVersionCopy.runOperation();
            }
            else
            {
                throw error(Error::missingRecord(funcName()));
            }
        }
    }
}

public boolean initFromArgs(Args args)
{
    boolean ret = true;

    if (args && args.record() && args.dataset() == tableNum(UPSBasePriceVersion))
    {
        callerBasePriceVersion = args.record();
    }
    else
    {
        ret = false;
    }

    return ret;
}

public void run()
{
    #OCCRetryCount

    if (callerBasePriceVersion)
    {
        UPSBasePriceVersion newBasePriceVersion;
        newBasePriceVersion.initFromUPSBasePriceVersion(callerBasePriceVersion);
        newBasePriceVersion.VersionId   = versionId;
        newBasePriceVersion.Name        = versionName;

        try
        {
            if (newBasePriceVersion.validateWrite())
            {
                ttsbegin;
                newBasePriceVersion.insert();
                ttscommit;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }
}

public boolean validate(Object calledFrom = null)
{
    boolean ret;

    ret = super(calledFrom);

    if (versionId)
    {
        if (UPSBasePriceVersion::exist(versionId))
        {
            ret = checkFailed(strFmt("@SYS153389", tablePName(UPSBasePriceVersion), tableStr(UPSBasePriceVersion)));
        }
    }
    else
    {
        ret = checkFailed(strFmt("@SYS84378", extendedTypeId2pname(extendedTypeNum(UPSBasePriceVersionId))));
    }

    return ret;
}
